export type IllustrationName = keyof typeof ILLUSTRATIONS

/** SVG 문자열 — 순수 JS·서버 렌더용. 옆에 이름 글자가 있으면(바로가기 칸 등) label을 비워 숨기고, 그림만으로 뜻을 전할 때만 label을 준다 */
export const illustrationSvg = ({ name, size = 40, label }: { name: IllustrationName; size?: number; label?: string }) => {
  const a11y = label ? `role="img" aria-label="${label.replace(/"/g, '&quot;')}"` : 'aria-hidden="true"'
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 32 32" fill="none" focusable="false" ${a11y}>${ILLUSTRATIONS[name]}</svg>`
}
